def _as_bool(value):
    """Parse a boolean option, accepting YAML/JSON booleans and strings."""
    if isinstance(value, str):
        lowered = value.strip().lower()
        if lowered == "true":
            return True
        if lowered == "false":
            return False
    return bool(value)


